import {useState, type ReactNode} from 'react'
import {LanguageSelection} from '@github-ui/code-scanning-shared/components/LanguageSelection'

export type LanguageSelectionForDefaultSetupProps = {
  description: ReactNode
  blankslateDescription: ReactNode
  hasMacOsRunner: boolean
  selectableLanguages: string[]
  selectedLanguages: string[]
  customBuildDocumentationUrl?: string
  hideCustomBuildInfo?: boolean
  headingLevel: 'h2' | 'h3'
  additionalHeaderClasses?: string
}

/**
 * Wrapper component for DefaultSetup that manages language selection state internally
 * and handles form submission through hidden inputs (like RunnerType pattern).
 *
 * For CodeQuality, use LanguageSelection directly with onChange prop.
 */
export function LanguageSelectionForDefaultSetup({
  description,
  blankslateDescription,
  hasMacOsRunner,
  selectableLanguages,
  selectedLanguages,
  customBuildDocumentationUrl,
  hideCustomBuildInfo,
  headingLevel,
  additionalHeaderClasses,
}: LanguageSelectionForDefaultSetupProps) {
  // Manage internal state for uncontrolled mode
  const [internalSelectedLanguages, setInternalSelectedLanguages] = useState<string[]>(() => selectedLanguages)

  // Track all languages that should remain visible (ever selected or selectable)
  const [visibleLanguages, setVisibleLanguages] = useState<string[]>(() => {
    const initial = new Set([...selectableLanguages, ...selectedLanguages])
    return Array.from(initial).sort()
  })

  const handleLanguageChange = (languages: string[]) => {
    setInternalSelectedLanguages(languages)

    // Update visible languages to include any newly selected languages
    setVisibleLanguages(prev => {
      const updated = new Set([...prev, ...languages])
      return Array.from(updated).sort()
    })
  }

  return (
    <div data-testid="language-selection-for-default-setup">
      {/* Form inputs for submission like RunnerType does */}
      <input type="hidden" name="config[languages_selected]" value="true" />
      {Array.from(new Set(internalSelectedLanguages)).map(language => (
        <input key={language} type="hidden" name="config[languages][]" value={language} />
      ))}

      <LanguageSelection
        description={description}
        blankslateDescription={blankslateDescription}
        hasMacOsRunner={hasMacOsRunner}
        selectableLanguages={visibleLanguages}
        selectedLanguages={internalSelectedLanguages}
        customBuildDocumentationUrl={customBuildDocumentationUrl}
        hideCustomBuildInfo={hideCustomBuildInfo}
        headingLevel={headingLevel}
        additionalHeaderClasses={additionalHeaderClasses}
        onChange={handleLanguageChange}
      />
    </div>
  )
}
