import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {Blankslate} from '@primer/react/experimental'
import {Checkbox, CheckboxGroup, FormControl, Heading, Link} from '@primer/react'

import styles from './LanguageSelection.module.css'
import type {ReactNode} from 'react'

const HIGH_FAILURE_LANGUAGES = new Set(['c-cpp', 'csharp', 'java-kotlin', 'swift'])
const PREVIEW_LANGUAGES = new Set()

export type LanguageSelectionProps = {
  description: ReactNode
  blankslateDescription: ReactNode
  hasMacOsRunner: boolean
  selectableLanguages: string[]
  selectedLanguages: string[]
  customBuildDocumentationUrl?: string // this isn't needed if hideCustomBuildInfo is true
  hideCustomBuildInfo?: boolean
  headingLevel: 'h2' | 'h3'
  additionalHeaderClasses?: string
  disabled?: boolean
  onChange: (selectedLanguages: string[]) => void
}

export function LanguageSelection({
  description,
  blankslateDescription,
  hasMacOsRunner,
  selectableLanguages,
  selectedLanguages,
  customBuildDocumentationUrl,
  hideCustomBuildInfo,
  headingLevel,
  additionalHeaderClasses,
  disabled = false,
  onChange,
}: LanguageSelectionProps) {
  // Always show union of selectableLanguages + selectedLanguages
  const sortedSelectableLanguages = () => {
    const allLanguages = new Set([...selectableLanguages, ...selectedLanguages])
    return Array.from(allLanguages).sort()
  }

  const languagesSet = new Set(selectedLanguages)
  const highFailureLanguagesPresent = selectableLanguages.some(language => HIGH_FAILURE_LANGUAGES.has(language))
  const swiftPresent = selectableLanguages.includes('swift')

  const handleLanguageChange = (language: string, checked: boolean) => {
    const newLanguages = new Set(selectedLanguages)
    if (checked) {
      newLanguages.add(language)
    } else {
      newLanguages.delete(language)
    }
    onChange(Array.from(newLanguages))
  }

  return (
    <div data-testid="language-selection">
      {selectableLanguages.length === 0 ? (
        <>
          <Heading as={headingLevel} className={styles.sectionTitle}>
            Languages
          </Heading>
          <div className="border rounded-2 mt-2">
            <Blankslate>
              <Blankslate.Heading>
                <span className={styles.blankslateHeadingText}>
                  No CodeQL supported languages to scan in this repository
                </span>
              </Blankslate.Heading>
              <Blankslate.Description>
                <span className={styles.blankslateDescriptionText}>{blankslateDescription}</span>
              </Blankslate.Description>
            </Blankslate>
          </div>
        </>
      ) : (
        <CheckboxGroup id="default-setup--languages">
          <CheckboxGroup.Label>
            <Heading as={headingLevel} className={`${styles.sectionTitle} ${additionalHeaderClasses || ''}`}>
              Languages
            </Heading>
          </CheckboxGroup.Label>
          <CheckboxGroup.Caption className={styles.sectionFieldDescription}>{description}</CheckboxGroup.Caption>

          <div className={styles.languageSelectionContainer}>
            {sortedSelectableLanguages().map((language: string) => (
              <FormControl
                key={language}
                id={`default-setup--language--${language}`}
                disabled={disabled || (!hasMacOsRunner && language === 'swift')}
              >
                <Checkbox
                  // Exclude from form data - wrapper component submits language data via hidden inputs
                  name={undefined}
                  checked={languagesSet.has(language)}
                  onChange={e => handleLanguageChange(language, e.target.checked)}
                />
                <FormControl.Label>
                  <span data-testid={`language-display-name-${language}`}>
                    {getLanguageDisplayName(language)}
                    {HIGH_FAILURE_LANGUAGES.has(language) && <span> *</span>}
                  </span>
                  {PREVIEW_LANGUAGES.has(language) && <BetaLabel className="ml-2" />}
                </FormControl.Label>
              </FormControl>
            ))}
          </div>
          {highFailureLanguagesPresent && !hideCustomBuildInfo && (
            <span className={styles.sectionFieldDescription} data-testid="custom-build-configuration-info">
              * These languages may{' '}
              <Link inline href={customBuildDocumentationUrl} target="_blank">
                require a custom build configuration
              </Link>{' '}
              for a successful setup.
              {swiftPresent && !hasMacOsRunner && (
                <>
                  {' '}
                  Swift requires <code>macOS</code> runners.
                </>
              )}
            </span>
          )}
        </CheckboxGroup>
      )}
    </div>
  )
}

function getLanguageDisplayName(language: string): string {
  switch (language) {
    case 'actions':
      return 'GitHub Actions'
    case 'c-cpp':
    case 'cpp':
      return 'C / C++'
    case 'csharp':
      return 'C#'
    case 'java':
    case 'java-kotlin':
      return 'Java / Kotlin'
    case 'javascript':
    case 'javascript-typescript':
      return 'JavaScript / TypeScript'
    default:
      return language.charAt(0).toUpperCase() + language.slice(1)
  }
}
