import {ActionList, ActionMenu, Autocomplete, FormControl} from '@primer/react'

import styles from './RunnerType.module.css'

export type RunnerLabelType = 'standard' | 'labeled'

export interface RunnerTypeProps {
  onlyLabeledRunners: boolean
  availableRunnerLabels: string[]
  runnerType: RunnerLabelType
  runnerLabel: string
  productName: string
  disabled?: boolean
  runnerLabelValidationDisabled?: boolean
  onChange: (payload: {runnerType: RunnerLabelType; runnerLabel: string}) => void
}

export function RunnerType({
  onlyLabeledRunners,
  availableRunnerLabels,
  runnerType,
  runnerLabel,
  productName,
  disabled = false,
  runnerLabelValidationDisabled = false,
  onChange,
}: RunnerTypeProps) {
  const noAvailableRunnerLabels = availableRunnerLabels.length === 0
  const shouldEnforceRunnerLabelValidation = !runnerLabelValidationDisabled
  const runnerLabelIsBlank = runnerLabel.trim() === ''
  const labeledRunnerOptionDisabled = shouldEnforceRunnerLabelValidation && noAvailableRunnerLabels
  const showNoLabelsWarning = shouldEnforceRunnerLabelValidation && noAvailableRunnerLabels
  const showRunnerLabelValidationError =
    runnerType === 'labeled' &&
    (runnerLabelIsBlank || (shouldEnforceRunnerLabelValidation && !availableRunnerLabels.includes(runnerLabel)))
  const runnerLabelValidationStatus = showRunnerLabelValidationError ? 'error' : undefined

  const runnerTypeOptionLabels = new Map<RunnerLabelType, string>([
    ['standard', 'Standard GitHub runner'],
    ['labeled', 'Labeled runner'],
  ])

  const runnerTypeOptionElements = [
    <ActionList.Item
      key="standard"
      selected={'standard' === runnerType}
      onSelect={() => {
        if (runnerType !== 'standard') {
          onChange({runnerType: 'standard', runnerLabel: ''})
        }
      }}
    >
      {runnerTypeOptionLabels.get('standard')}
      <ActionList.Description variant="block">
        {productName} will use standard GitHub runners to run scans.
      </ActionList.Description>
    </ActionList.Item>,
    <ActionList.Item
      key="labeled"
      selected={'labeled' === runnerType}
      disabled={labeledRunnerOptionDisabled}
      onSelect={() => {
        if (runnerType !== 'labeled') {
          onChange({runnerType: 'labeled', runnerLabel})
        }
      }}
    >
      {runnerTypeOptionLabels.get('labeled')}
      <ActionList.Description variant="block">
        {showNoLabelsWarning && (
          <span className="d-block mb-1 color-fg-attention">This repository has no available runner labels.</span>
        )}
        <span>{productName} will use the labeled GitHub or self-hosted runners defined below.</span>
      </ActionList.Description>
    </ActionList.Item>,
  ]

  const runnerLabelField = (
    <div className={styles.runnerContainer}>
      <div className={styles.runnerLabelRow}>
        <span className={styles.sectionFieldLabel}>Runner label</span>
        <span className={styles.sectionFieldDescription}>
          Enter label of an existing self-hosted or GitHub-hosted runner.
        </span>
      </div>
      <FormControl disabled={disabled}>
        <FormControl.Label id="runnerlabelautocomplete" visuallyHidden>
          Runner label
        </FormControl.Label>
        <Autocomplete>
          <Autocomplete.Input
            validationStatus={runnerLabelValidationStatus}
            openOnFocus
            disabled={disabled}
            onChange={e => onChange({runnerType, runnerLabel: e.target.value})}
            value={runnerLabel}
          />
          {shouldEnforceRunnerLabelValidation && (
            <Autocomplete.Overlay>
              <Autocomplete.Menu
                items={availableRunnerLabels.map(label => ({id: label, text: label}))}
                selectedItemIds={[runnerLabel]}
                onSelectedChange={itemOrItems => {
                  const {text = ''} = (Array.isArray(itemOrItems) ? itemOrItems.slice(-1)[0] : itemOrItems) ?? {}
                  if (text !== runnerLabel) {
                    onChange({runnerType, runnerLabel: text})
                  }
                }}
                aria-labelledby="autocompleteLabel"
                selectionVariant="single"
              />
            </Autocomplete.Overlay>
          )}
          <input type="hidden" name="config[runner_label]" value={runnerLabel} />
        </Autocomplete>
      </FormControl>
    </div>
  )

  if (onlyLabeledRunners) {
    return (
      <>
        <input type="hidden" name="config[runner_type]" value="labeled" />
        <div>{runnerLabelField}</div>
      </>
    )
  }

  return (
    <>
      <div className={styles.runnerTypeRow}>
        <div>
          <span className={styles.sectionFieldLabel}>Runner type</span>
          <span className={styles.sectionFieldDescription}>
            Select the runner used for {productName.toLowerCase()}.
          </span>
        </div>
        <ActionMenu>
          <input type="hidden" name="config[runner_type]" value={runnerType} />
          <ActionMenu.Button disabled={disabled} data-testid="query-suite-runner-type-label">
            {runnerTypeOptionLabels.get(runnerType)}
          </ActionMenu.Button>
          <ActionMenu.Overlay width="medium">
            <ActionList showDividers selectionVariant="single" role="menu" aria-label="Runner type">
              {runnerTypeOptionElements}
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </div>

      {runnerType === 'labeled' && <div className={styles.runnerLabelInputContainer}>{runnerLabelField}</div>}
    </>
  )
}
